{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Apply the specified bounded rarity scale to input embeddings using counts from training interactions only. Store scales as a persistent model buffer so the generated predictor imports the updated architecture and restores identical scales from each category's single checkpoint. Preserve learned embeddings, GRU topology, readout, loss, optimizer, and routing.",
      "edits": [
        {
          "find": "DATA_DIR = os.environ.get(\"GAGC_DATA_DIR\", \"./input/trainval\")",
          "replace": "DATA_DIR = os.environ['GAGC_DATA_DIR']"
        },
        {
          "find": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        dropout = dropout_rate if num_layers > 1 else 0.0",
          "replace": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.register_buffer(\"input_scale\", torch.ones(itemnum + 1))\n        self.input_scale[0] = 0.0\n        dropout = dropout_rate if num_layers > 1 else 0.0"
        },
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq) * self.input_scale[seq].unsqueeze(-1))"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq) * self.input_scale[seq].unsqueeze(-1))"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    counts = np.zeros(itemnum + 1, dtype=np.float64)\n    for history in user_train.values():\n        np.add.at(counts, np.asarray(history, dtype=np.int64), 1.0)\n    observed_counts = counts[1:][counts[1:] > 0]\n    median_count = float(np.median(observed_counts)) if observed_counts.size else 0.0\n    input_scale = 1.0 + 0.1 * np.tanh(np.log1p(median_count) - np.log1p(counts))\n    input_scale[0] = 0.0\n    with torch.no_grad():\n        model.input_scale.copy_(torch.as_tensor(input_scale, dtype=torch.float32, device=device))\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
      ]
    }
  ],
  "change_summary": "Add training-count rarity scaling to GRU inputs across all four datasets. Scales persist in each model checkpoint and load through the existing predictor writer's dynamic model import."
}
